import re,html
for f in ['u1.html','u1a.html']:
    s=open(f).read()
    t=re.sub(r'<[^>]+>',' ',s); t=html.unescape(t); t=re.sub(r'\s+',' ',t)
    print('==',f,len(t))
    for kw in ['3.08','1.42','28.8','abstract','Abstract']:
        for m in list(re.finditer(re.escape(kw),t))[:2]:
            print('  ',kw,'>>>',t[max(0,m.start()-300):m.start()+400])
"

